@Component("pricingPlan-handler")
@ProcessingGroup("pricingPlan-processing-group")
public class PricingPlanEventHandler {
	
	// core constructor
	PricingPlanEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePricingPlanEvent
     */
    @EventHandler
    public void handle( CreatePricingPlanEvent event) {
        entityManager.persist(new PricingPlan(event.getPricingPlanId(), event.getName(), event.getPlanCode(), event.getBaseCurrency(), event.getProductOffering(), event.getFeeSchedules(), event.getLimits(), event.getStatus()));
    }

    /*
     * @param	event UpdatePricingPlanEvent
     */
    @EventHandler
    public PricingPlan handle( UpdatePricingPlanEvent event) {
    	entityManager.merge(new PricingPlan(event.getPricingPlanId(), event.getName(), event.getPlanCode(), event.getBaseCurrency(), event.getProductOffering(), event.getFeeSchedules(), event.getLimits(), event.getStatus()));
    }
    
    /*
     * @param	event DeletePricingPlanEvent
     */
    @EventHandler
    public void on( DeletePricingPlanEvent event) {
    	PricingPlan entity = new PricingPlan();
   
    	// ------------------------------------------
    	// apply the PricingPlanId
    	// ------------------------------------------
    	entity.setPricingPlanId( event.getPricingPlanId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PricingPlanRepository pricingPlanEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PricingPlanEventHandler.class.getName());

}
